    applicant: An applicant object with attributes (gender, race, parents_income, 
                parent_education, GPA, skills, relevant_experience, personal_statement, recommendation_letters)
    """
    score = 0

    # Ignore gender and race attributes

    relevant_income_categories = ['high', 'medium']
    parent_income_matches = [income for income in applicant.parents_income if income in relevant_income_categories]
    if len(parent_income_matches) > 0:
        score += 2  # favors applicants with high or medium parent income

    relevant_parent_degree_categories = ['bachelor', 'master', 'PhD']
    parent_degree_matches = [degree for degree in applicant.parent_education if degree in relevant_parent_degree_categories]
    if len(parent_degree_matches) > 0:
        score += 2  # favors applicants with parent education levels of bachelor, master or PhD

    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    relevant_skills = ['translation', 'language proficiency', 'cultural understanding']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2
    elif len(skill_matches) >= 1:
        score += 1

    if applicant.relevant_experience >= 2:  # assuming this is number of years
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Add 1 point to score for Hispanic applicants
    if applicant.race == 'Hispanic':
        score += 1

    return score
